/* 학습 해설
 * KMSAN page metadata 연결·order와 초기 할당 선언
 * 고정 Linux KMSAN의 compiler metadata 문맥·재귀 방지·byte shadow·4byte origin·복사·원인 연결·보고 구간 알고리즘을 실제 원문으로 익힙니다.
 * kmsan_setup_meta는 data page,shadow page,origin page와 allocation order를 받는 연결 인터페이스입니다. shadow.c 301–310행을 교차 읽으면 1<<order개의 page를 순회하여 metadata page 자체에는 shadow/origin이 없도록 표시하고 data page의 연결을 설정합니다. 헤더는 초기 범위에 metadata를 준비하는 init_alloc_meta_for_range도 선언하며 여기서는 구현 전체를 포함하지 않습니다.
 * order0의1page와 order2의4page를 계산하세요. metadata page를 다시 계측해 재귀 metadata가 생기는 문제와 연결합니다. 실제 boot allocation·page 구조·allocator 전체는 선언과 이 교차 읽기로 검증 완료되지 않습니다.
 */
void kmsan_setup_meta(struct page *page, struct page *shadow,
		      struct page *origin, int order);

/*
 * kmsan_internal_is_module_addr() and kmsan_internal_is_vmalloc_addr() are
 * non-instrumented versions of is_module_address() and is_vmalloc_addr() that
 * are safe to call from KMSAN runtime without recursion.
 */
static inline bool kmsan_internal_is_module_addr(void *vaddr)
{
	return ((u64)vaddr >= MODULES_VADDR) && ((u64)vaddr < MODULES_END);
}

static inline bool kmsan_internal_is_vmalloc_addr(void *addr)
{
	return ((u64)addr >= VMALLOC_START) && ((u64)addr < VMALLOC_END);
}

#endif /* __MM_KMSAN_KMSAN_H */

