/* 학습 해설
 * KMSAN page 연결·데이터 page 와 두 metadata page
 * 고정 KMSAN 원문의 metadata 주소 분류·page 연결·할당과 해제·가상 mapping·실패 자원 정리를 읽어 기술의 원리와 사용 계약을 배웁니다.
 * shadow.c는 page의 kmsan_shadow와 kmsan_origin 연결을 macro로 읽습니다. page_has_metadata는 둘 다 있어야 참입니다. shadow_ptr_for와 origin_ptr_for는 연결한 metadata page의 page_address를 얻습니다. 실제 데이터 page와 추적용 두 page를 구별해야 하며 한 연결만 존재하는 상태를 완전한 metadata로 읽지 않습니다.
 * data page에서 shadow·origin page로 화살표를 두 개 그리세요. page_has_metadata의 &&와 pointer 조회의 전제를 주석으로 씁니다. fixture는 두 연결과 하나가 빠진 상태를 비교하며 실제 struct page 전체의 수명은 모델 밖입니다.
 */
static bool page_has_metadata(struct page *page)
{
	return shadow_page_for(page) && origin_page_for(page);
}

static void set_no_shadow_origin_page(struct page *page)
{
	shadow_page_for(page) = NULL;
	origin_page_for(page) = NULL;
}

/*
 * Dummy load and store pages to be used when the real metadata is unavailable.
 * There are separate pages for loads and stores, so that every load returns a
 * zero, and every store doesn't affect other loads.
 */
static char dummy_load_page[PAGE_SIZE] __aligned(PAGE_SIZE);
static char dummy_store_page[PAGE_SIZE] __aligned(PAGE_SIZE);

static unsigned long vmalloc_meta(void *addr, bool is_origin)
{
	unsigned long addr64 = (unsigned long)addr, off;

	KMSAN_WARN_ON(is_origin && !IS_ALIGNED(addr64, KMSAN_ORIGIN_SIZE));
	if (kmsan_internal_is_vmalloc_addr(addr)) {
		off = addr64 - VMALLOC_START;

