/* 학습 해설
 * KMSAN dummy load·store page·상태 간섭 방지
 * 고정 KMSAN 원문의 metadata 주소 분류·page 연결·할당과 해제·가상 mapping·실패 자원 정리를 읽어 기술의 원리와 사용 계약을 배웁니다.
 * 실제 metadata가 없을 때 사용하는 dummy_load_page와 dummy_store_page는 각각 PAGE_SIZE 크기·정렬입니다. load page는 zero metadata를 제공하고 store는 별도 page로 향해 다른 load에 영향을 주지 않습니다. 같은 요청 쌍 안에서는 shadow와 origin이 같은 dummy page를 가리키지만 load와 store의 공간은 별개입니다.
 * dummy store에 FF를 쓴 뒤 dummy load의 0이 유지되는지 비교하세요. fixture는 이 byte 결과를 검사했습니다. 실제 data 값이 0으로 바뀐다는 뜻이 아니라 metadata를 통한 초기화 해석임을 확인합니다.
 */
struct shadow_origin_ptr kmsan_get_shadow_origin_ptr(void *address, u64 size,
						     bool store)
{
	struct shadow_origin_ptr ret;
	void *shadow;

	/*
	 * Even if we redirect this memory access to the dummy page, it will
	 * go out of bounds.
	 */
	KMSAN_WARN_ON(size > PAGE_SIZE);

	if (!kmsan_enabled)
		goto return_dummy;

	KMSAN_WARN_ON(!kmsan_metadata_is_contiguous(address, size));
	shadow = kmsan_get_metadata(address, KMSAN_META_SHADOW);
	if (!shadow)
		goto return_dummy;

	ret.shadow = shadow;
	ret.origin = kmsan_get_metadata(address, KMSAN_META_ORIGIN);
	return ret;

return_dummy:
	if (store) {

