/* 학습 해설
 * KMSAN boot metadata 할당·범위 정렬과 두 공간
 * 고정 KMSAN 원문의 metadata 주소 분류·page 연결·할당과 해제·가상 mapping·실패 자원 정리를 읽어 기술의 원리와 사용 계약을 배웁니다.
 * boot 초기화는 start를 페이지 아래로 정렬하고 end-start를 페이지 위로 올려 size를 구합니다. shadow와 origin을 각각 memblock_alloc(size,PAGE_SIZE)로 준비하며 하나라도 없으면 panic합니다. 각 data page에 두 연결을 설정하고 metadata page 자체의 연결은 비웁니다.
 * start가 page1+3, end가 page2+5이면 두 page 범위임을 계산하세요. fixture는 size, alignment, 연결 결과와 할당 실패의 panic 모델을 확인했습니다. 실제 memblock boot나 panic 출력을 실행하지는 않습니다.
 */
void __init kmsan_init_alloc_meta_for_range(void *start, void *end)
{
	struct page *shadow_p, *origin_p;
	void *shadow, *origin;
	struct page *page;
	u64 size;

	start = (void *)PAGE_ALIGN_DOWN((u64)start);
	size = PAGE_ALIGN((u64)end - (u64)start);
	shadow = memblock_alloc(size, PAGE_SIZE);
	origin = memblock_alloc(size, PAGE_SIZE);

	if (!shadow || !origin)
		panic("%s: Failed to allocate metadata memory for early boot range of size %llu",
		      __func__, size);

	for (u64 addr = 0; addr < size; addr += PAGE_SIZE) {
		page = virt_to_page_or_null((char *)start + addr);
		shadow_p = virt_to_page((char *)shadow + addr);
		set_no_shadow_origin_page(shadow_p);
		shadow_page_for(page) = shadow_p;
		origin_p = virt_to_page((char *)origin + addr);
		set_no_shadow_origin_page(origin_p);
		origin_page_for(page) = origin_p;
	}
}

