/* 학습 해설
 * KMSAN asm 주소 분류·사용자 범위와 metadata 존재
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * is_bad_asm_addr는 주소 공간이 겹치지 않는 arch 설정이면 addr<TASK_SIZE를 먼저 거부합니다. 그 외에는 shadow lookup이 없으면 거부합니다. size와 is_store 인자는 이 본문에서 사용하지 않습니다. 전체 주소 범위의 끝까지 검사하는 일반 access validator가 아니라 inline asm annotation을 생략할지 결정하는 제한된 분류입니다.
 * 설정 0/1에서 낮은 주소와 추적 주소를 비교하세요. fixture는 숫자 주소만 분류하고 실제 낮은 주소를 역참조하지 않습니다. 실제 asm의 접근 길이·mapping·수명은 underlying 코드의 계약으로 유지해야 합니다.
 */
static inline bool is_bad_asm_addr(void *addr, uintptr_t size, bool is_store)
{
	if (IS_ENABLED(CONFIG_ARCH_HAS_NON_OVERLAPPING_ADDRESS_SPACE) &&
	    (u64)addr < TASK_SIZE)
		return true;
	if (!kmsan_get_metadata(addr, KMSAN_META_SHADOW))
		return true;
	return false;
}

static inline struct shadow_origin_ptr
get_shadow_origin_ptr(void *addr, u64 size, bool store)
{
	unsigned long ua_flags = user_access_save();
	struct shadow_origin_ptr ret;

	ret = kmsan_get_shadow_origin_ptr(addr, size, store);
	user_access_restore(ua_flags);
	return ret;
}

/*
 * KMSAN instrumentation functions follow. They are not declared elsewhere in
 * the kernel code, so they are preceded by prototypes, to silence
 * -Wmissing-prototypes warnings.
 */

