/* 학습 해설
 * KMSAN asm 출력 초기화·놓친 store의 best effort
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * asm store hook은 inline assembly 출력이 초기화된 것으로 표시하려 unchecked unpoison을 수행합니다. compiler가 실제 asm 내부 store를 놓쳐 거짓 보고가 생기는 것을 줄이는 best-effort 정책입니다. 반대로 진짜 미초기화 문제를 가릴 수도 있다는 공식 문서의 한계가 있습니다. annotation 자체가 data 값을 생성하지는 않습니다.
 * asm이 실제로 기록한 범위와 unpoison 범위를 맞춰 보세요. fixture는 인자와 unchecked 상태를 기록하며 asm instruction이나 실제 MSan compiler output을 실행하지 않습니다. 추적 정책과 데이터의 초기화 증명을 구별합니다.
 */
void __msan_instrument_asm_store(void *addr, uintptr_t size)
{
	unsigned long ua_flags;

	if (!kmsan_enabled)
		return;

	ua_flags = user_access_save();
	/*
	 * Most of the accesses are below 32 bytes. The exceptions so far are
	 * clwb() (64 bytes), FPU state (512 bytes) and chsc() (4096 bytes).
	 */
	if (size > 4096) {
		WARN_ONCE(1, "assembly store size too big: %ld\n", size);
		size = 8;
	}
	if (is_bad_asm_addr(addr, size, /*is_store*/ true)) {
		user_access_restore(ua_flags);
		return;
	}
	/* Unpoisoning the memory on best effort. */
	kmsan_internal_unpoison_memory(addr, size, /*checked*/ false);
	user_access_restore(ua_flags);
}
EXPORT_SYMBOL(__msan_instrument_asm_store);

