/* 학습 해설
 * KMSAN asm 크기 경계·4096 초과는 8로 줄인다
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * asm hook은 size>4096이면 WARN_ONCE를 남기고 size를 8로 바꿉니다. 주석은 흔한 접근은 32byte 미만,예외는 clwb64·FPU512·chsc4096이라고 설명합니다. size4097을 4096으로 clamp 하는 것이 아니라 8로 대체하는 실제 분기입니다. 이 정책이 원래 거대한 접근 범위를 모두 검사한다는 뜻은 아닙니다.
 * 4096과 4097의 분기를 비교하세요. fixture는 4097에서 실제 notification 길이 8과 경고를 확인했습니다. 거대한 주소 접근은 수행하지 않고 인자 전달만 검사합니다. WARN_ONCE 모델은 이벤트를 세며 실제 once-only 출력 정책을 실행하지 않습니다.
 */
void __msan_instrument_asm_store(void *addr, uintptr_t size)
{
	unsigned long ua_flags;

	if (!kmsan_enabled)
		return;

	ua_flags = user_access_save();
	/*
	 * Most of the accesses are below 32 bytes. The exceptions so far are
	 * clwb() (64 bytes), FPU state (512 bytes) and chsc() (4096 bytes).
	 */
	if (size > 4096) {
		WARN_ONCE(1, "assembly store size too big: %ld\n", size);
