/* 학습 해설
 * KMSAN memset hook·채우는 값 c의 shadow를 받지 못한다
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * memset hook는 실제 byte fill 뒤 destination을 unchecked unpoison 합니다. 주석은 Clang이 이 경로에 c의 parameter metadata를 전달하지 않아 c의 shadow로 dst shadow를 만들 수 없다고 설명합니다. 데이터를 어떤 값으로 썼다는 사실과 그 값 자체가 초기화됐는지를 추적할 정보의 부족을 구별합니다.
 * 정상 초기화된 c23의 실제 byte 결과를 fixture에서 확인하세요. 미초기화 C 값을 실제로 읽는 예를 실행하지 않습니다. 이 hook의 limitation을 이유로 아무 uninitialized 값이나 안전하게 사용해도 된다고 해석하지 않습니다.
 */
void *__msan_memset(void *dst, int c, uintptr_t n)
{
	depot_stack_handle_t origin;
	void *result;
	u64 shadow;

	get_param0_metadata(&shadow, &origin);
	result = __memset(dst, c, n);
	if (!kmsan_enabled || kmsan_in_runtime())
		return result;

	kmsan_enter_runtime();
	/*
	 * Clang doesn't pass parameter metadata here, so it is impossible to
	 * use shadow of @c to set up the shadow for @dst.
	 */
	kmsan_internal_unpoison_memory(dst, n, /*checked*/ false);
	kmsan_leave_runtime();

	set_retval_metadata(shadow, origin);
	return result;
}
