/* 학습 해설
 * KMSAN local unpoison hook·checked와 runtime 균형
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * unpoison_alloca는 비활성 또는 runtime이면 반환합니다. 정상 경로에서는 guard 안에서 checked true로 internal_unpoison을 호출합니다. asm hook와 달리 runtime bail out이 있으며 metadata 추적 범위를 확인하는 checked 경로입니다. compiler의 local 초기화 사실을 추적 상태와 일치시키는 역할입니다.
 * alloca poison, local unpoison과 asm unpoison의 guard·checked 차이를 표로 적으세요. fixture는 local 길이와 checked, 비활성·중첩 생략과 guard 복구를 확인했습니다. 실제 local 초기화는 프로그램의 정상 쓰기 계약입니다.
 */
void __msan_unpoison_alloca(void *address, uintptr_t size)
{
	if (!kmsan_enabled || kmsan_in_runtime())
		return;

	kmsan_enter_runtime();
	kmsan_internal_unpoison_memory(address, size, /*checked*/ true);
	kmsan_leave_runtime();
}
EXPORT_SYMBOL(__msan_unpoison_alloca);

