/* 학습 해설
 * KMSAN bit shadow 원리·데이터 0과초기화 0은다르다
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * 각 data byte에는 shadow byte가 대응하며 shadow bit1은 해당 data bit가 미초기화라는 뜻입니다. data가 0xff 여도 정상 상수로 초기화했다면 shadow는 0 입니다. 데이터가 우연히 0 인 것과 initialized shadow0은 다릅니다. 비 ZERO heap와 초기화하지 않은 stack은 poison 대상으로 설명합니다.
 * data0xff와 shadow0을 나란히 그리세요. 값이 0이어야 initialized라고 외우지 않습니다. 실제 데이터와 추적 상태를 구별하고 OR의 bit 별 불확실성 예제와 연결합니다.
 */
void *__msan_memset(void *dst, int c, uintptr_t n)
{
	depot_stack_handle_t origin;
	void *result;
	u64 shadow;

	get_param0_metadata(&shadow, &origin);
	result = __memset(dst, c, n);
	if (!kmsan_enabled || kmsan_in_runtime())
		return result;

	kmsan_enter_runtime();
	/*
	 * Clang doesn't pass parameter metadata here, so it is impossible to
	 * use shadow of @c to set up the shadow for @dst.
	 */
	kmsan_internal_unpoison_memory(dst, n, /*checked*/ false);
	kmsan_leave_runtime();

	set_retval_metadata(shadow, origin);
	return result;
}
EXPORT_SYMBOL(__msan_memset);

