/* 학습 해설
 * KMSAN OR shadow 계산·known1이 unknown을덮는 bit
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * 문서의 32bit 예제에서 a=0x000000ff는 initialized이고 b는 모두 unknown 입니다. c=a|b의 낮은 8bit는 a의 known1로 결정됩니다. 높은 24bit는 a가 0이라 b의 unknown이 남아 shadow(c)=0xffffff00 입니다. 실제 미초기화 b를 C로 읽는 실행이 아니라 문서의 bit 추적 원리입니다.
 * 한 bit의 0,1,unknown으로 OR 표를 만드세요. known1|unknown은 known1, known0|unknown은 unknown 입니다.32bit shadow를 독립적으로 계산해 답지와 비교하세요. 모든 LLVM 명령의 전파를 검증한 것은 아닙니다.
 */
void *__msan_memmove(void *dst, const void *src, uintptr_t n)
{
	depot_stack_handle_t origin;
	void *result;
	u64 shadow;

	get_param0_metadata(&shadow, &origin);
	result = __memmove(dst, src, n);
	if (!n)
		/* Some people call memmove() with zero length. */
		return result;
	if (!kmsan_enabled || kmsan_in_runtime())
		return result;

	kmsan_enter_runtime();
	kmsan_internal_memmove_metadata(dst, (void *)src, n);
	kmsan_leave_runtime();

	set_retval_metadata(shadow, origin);
	return result;
}
EXPORT_SYMBOL(__msan_memmove);

