/* 학습 해설
 * KMSAN origin 정밀도·두 short가한 4byte 원인을공유
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * 공식 combine 예제의 두 short는 한 4byte origin을 공유합니다. 앞 short가 initialized, 뒤 short가 unknown이면 문서의 x86 shadow는 0xffff0000이고 뒤 origin이 남습니다. 둘 다 unknown이면 나중에 쓴 두 번째 origin만 보존합니다. bit shadow의 정밀도와 4byte origin의 정밀도는 다릅니다.
 * 두 short의 data·shadow·공유 origin을 그리세요. initialized 앞 short가 같은 origin을 가져도 shadow0이면 보고에 사용되지 않습니다. 모든 endian layout이나 compiler store 순서로 일반화하지 않습니다.
 */
depot_stack_handle_t __msan_chain_origin(depot_stack_handle_t origin)
{
	depot_stack_handle_t ret = 0;
	unsigned long ua_flags;

	if (!kmsan_enabled || kmsan_in_runtime())
		return ret;

	ua_flags = user_access_save();

	/* Creating new origins may allocate memory. */
	kmsan_enter_runtime();
	ret = kmsan_internal_chain_origin(origin);
	kmsan_leave_runtime();
	user_access_restore(ua_flags);
	return ret;
}
EXPORT_SYMBOL(__msan_chain_origin);

